export const esc=(value='')=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const numberFormats=new Map();
export const fmt=(v,d=0)=>{if(v===null||v===undefined||v===Infinity)return '∞';const n=Number(v)||0;if(Math.abs(n)>=1e9)return (n/1e9).toFixed(2)+'B';if(Math.abs(n)>=1e6)return (n/1e6).toFixed(2)+'M';if(Math.abs(n)>=1e4)return (n/1e3).toFixed(1)+'k';if(!numberFormats.has(d))numberFormats.set(d,new Intl.NumberFormat('zh-CN',{maximumFractionDigits:d,minimumFractionDigits:0}));return numberFormats.get(d).format(n);};
export const pct=(a,b)=>Math.min(100,Math.max(0,b>0?a/b*100:0));
export const rate=(n)=>`${n>0?'+':''}${fmt(n,2)}/秒`;
export const RESOURCE_CELLS={honey:'honey',wood:'wood',minerals:'stone',iron:'iron',coal:'coal',gold:'gold',science:'science',culture:'culture',faith:'faith',bear:'bear',spice:'berries',timeCrystal:'crystal',...Object.fromEntries(Object.keys(semanticResources).map(k=>[k,k]))};
export const BUILDING_CELLS={aqueduct:'aqueduct',quarry:'quarry',mint:'mint',chapel:'chapel',unicornPasture:'unicornPasture',ziggurat:'ziggurat',hive:'beehive',hut:'bearHut',logHouse:'bearHut',mansion:'bearHut',library:'library',barn:'barn',lumberMill:'logyard',mine:'mine',workshop:'workshop',smelter:'forge',warehouse:'warehouse',temple:'shrine',observatory:'observatory',academy:'academy',harbor:'market',reactor:'factory',pasture:'beehive',amphitheatre:'market',factory:'factory',tradepost:'market',steamworks:'factory',magneto:'factory',calciner:'forge',oilWell:'mine',accelerator:'factory',biolab:'biolab',aiCore:'academy',dataCenter:'library',solarFarm:'factory',hydroPlant:'factory',broadcastTower:'market',spaceport:'launchpad',zebraOutpost:'bearHut',zebraWorkshop:'workshop',zebraForge:'forge',stasisPod:'timegate',ivoryTemple:'shrine',brewery:'workshop',chronosphere:'timegate' };
Object.assign(BUILDING_CELLS,Object.fromEntries(Object.keys(semanticBuildings).map(k=>[k,k])),{logHouse:'loghouse',mansion:'manor'});
function semanticSprite(entry,key,kind,cls=''){if(!entry)return '';const c=entry.crop;return `<span class="atlas semantic-art semantic-${kind} ${entry.sheet} ${cls}" data-art-kind="${kind}" data-art-key="${esc(key)}" aria-hidden="true"><span class="atlas-sprite" style="width:min(94cqw, ${94*c.width/c.height}cqh);height:min(94cqh, ${94*c.height/c.width}cqw);background-size:${entry.width/c.width*100}% ${entry.height/c.height*100}%;background-position:${c.x/(entry.width-c.width)*100}% ${c.y/(entry.height-c.height)*100}%"></span></span>`;}

function paintedBuilding(key,cls=''){const s=paintedBuildings[key];if(!s)return '';const c=s.crop;return `<span class="atlas building-art scene-atlas painted-building painted-${s.sheet} ${cls}" data-art-key="${key}" aria-hidden="true"><span class="atlas-sprite" style="width:min(96cqw, ${96*c.width/c.height}cqh);height:min(96cqh, ${96*c.height/c.width}cqw);background-size:${s.width/c.width*100}% ${s.height/c.height*100}%;background-position:${c.x/(s.width-c.width)*100}% ${c.y/(s.height-c.height)*100}%"></span></span>`;}
function workplaceDetail(b,vm,ui){const a=buildingActivity(b,vm,ui);if(!a||(!a.working&&!a.stock))return '';return `<span class="workplace-detail activity-${a.kind} ${a.working?'is-producing':'is-still'}" data-activity="${a.kind}" data-producing="${a.working}" aria-hidden="true">${a.kind==='bees'?'<i class="work-bee bee-a"></i><i class="work-bee bee-b"></i>':a.kind==='forge'?'<i class="work-smoke"></i><i class="work-ember"></i>':a.kind==='study'?`<span class="study-pages">${art('resource','science')}</span>`:`<span class="work-cargo">${art('resource',a.resource)}</span>`}</span>`;}
export function art(kind,id,cls=''){if(kind==='research')return semanticSprite(researchArt[id],id,'research',cls);if(kind==='building'&&semanticBuildings[id])return semanticSprite(semanticBuildings[id],id,'building',cls);if(kind!=='building'&&semanticResources[id])return semanticSprite(semanticResources[id],id,'resource',cls);if(kind==='building'&&paintedBuildings[BUILDING_CELLS[id]||id])return paintedBuilding(BUILDING_CELLS[id]||id,cls);if(kind==='building'&&id==='workshop')return `<span class="atlas building-art soft-workshop ${cls}" data-art-key="workshop" aria-hidden="true"><img src="./art/workshop-soft.webp" alt="" draggable="false"></span>`;if(kind==='building'&&coreAtlas.crops[BUILDING_CELLS[id]||id])return sceneArt('core',BUILDING_CELLS[id]||id,cls);if(kind==='building'&&(BUILDING_CELLS[id]||id)==='beehive')return sceneArt('hives','hive',cls);if(kind!=='building'&&RESOURCE_CELLS[id]==='bear')return sceneArt('bears','idleFront',`resource-art ${cls}`);const map=kind==='building'?BUILDING_CELLS:RESOURCE_CELLS;const crops=atlasCrops[kind==='building'?'buildings-atlas':'resources-atlas'];const c=crops[map[id]||id];if(!c)return `<span class="atlas unassigned-art ${cls}" data-unassigned-art="${esc(kind+':'+id)}" aria-hidden="true">${icon('help')}</span>`;const max=Math.max(c.width,c.height);return `<span class="atlas ${kind}-art ${cls}" aria-hidden="true"><span class="atlas-sprite" style="width:${90*c.width/max}%;height:${90*c.height/max}%;background-size:${1254/c.width*100}% ${1254/c.height*100}%;background-position:${c.x/(1254-c.width)*100}% ${c.y/(1254-c.height)*100}%"></span></span>`;}
function outfitSprite(key,cls=''){const c=outfitAtlas.crops[key];return `<span class="atlas scene-atlas outfit-bear-art ${cls}" data-outfit="${c.job}" data-pose="${key}" aria-hidden="true"><span class="atlas-sprite" style="width:100cqh;height:100cqh;background-size:${outfitAtlas.width/c.width*100}% ${outfitAtlas.height/c.height*100}%;background-position:${c.x/(outfitAtlas.width-c.width)*100}% ${c.y/(outfitAtlas.height-c.height)*100}%"></span></span>`;}
export function sceneArt(atlas,key,cls=''){if(atlas==='workers'&&outfitAtlas.crops[key])return outfitSprite(key,cls);if(['core','buildings'].includes(atlas)&&semanticBuildings[key])return semanticSprite(semanticBuildings[key],key,'building',cls);if(['core','buildings','hives'].includes(atlas)&&paintedBuildings[key])return paintedBuilding(key,cls);if(['core','buildings'].includes(atlas)&&key==='workshop')return art('building','workshop',cls);const isBear=atlas==='bears'||atlas==='workers',isHive=atlas==='hives'||(atlas==='buildings'&&key==='apiary'),sheet=isBear?bearAtlas:isHive?hiveAtlas:atlas==='core'||(atlas==='buildings'&&coreAtlas.crops[key])?coreAtlas:growthAtlases[atlas],pose=key==='idleWalk'?'idleFront':key,c=sheet?.crops?.[pose];if(!c)return '<span class="atlas" aria-hidden="true"></span>';const max=Math.max(c.width,c.height);return `<span class="atlas scene-atlas ${atlas}-art ${sheet===coreAtlas?'core-building-art':''} ${isBear?'reference-bear-art':isHive?'reference-hive-art':''} ${cls}" aria-hidden="true"><span class="atlas-sprite" style="width:min(96cqw, ${96*c.width/c.height}cqh);height:min(96cqh, ${96*c.height/c.width}cqw);background-size:${sheet.width/c.width*100}% ${sheet.height/c.height*100}%;background-position:${c.x/(sheet.width-c.width)*100}% ${c.y/(sheet.height-c.height)*100}%"></span></span>`;}
export function resource(vm,id){return vm.resources.find(r=>r.id===id)||{id,name:id,value:0,max:null,rate:0};}
export const discovered=c=>!!c&&(c.unlocked===true||c.owned>0||c.assigned>0||c.completed===true||c.active===true);
export const knownBuilding=(vm,c)=>discovered(c)&&(c.id!=='ivoryTemple'||c.owned>0||(c.costs||[]).every(cost=>vm.resources.some(r=>r.id===cost.id&&r.visible)));
export const navs=[['home','home','林间'],['build','build','建造'],['research','research','知识'],['village','bears','熊村'],['more','more','更多']];
export function cardsFor(vm,section){if(section==='gifts')return vm.gifts?.cards||[];if(section==='leadership')return vm.leadership?.cards||[];if(section==='queueOptions')return vm.queue?.options||[];if(section==='engineers')return vm.engineers?.cards||[];if(section==='embassies')return [...(vm.embassies||[]),...(vm.diplomacy?.cards||vm.diplomacy?.actions||[])];if(section==='diplomacy')return vm.diplomacy?.cards||vm.diplomacy?.actions||[];if(section==='workshopActions')return [...(vm.workshopDynamics?.cards||[]),...(vm.workshopDynamics?.actions||[])];const key={faith:'faithCards',space:'spaceCards',challenges:'challengeCards'}[section];return key&&vm.progression?.[key]||(['metaphysics','time','progressionActions'].includes(section)?vm.progression?.[section==='progressionActions'?'actions':section]:vm[section])||[];}
export function visibleNavs(vm){return navs.filter(([id])=>id!=='research'||vm.science.some(discovered)).filter(([id])=>id!=='village'||vm.bears?.max>0||vm.bears?.value>0||vm.gifts?.cards?.some(c=>c.visible!==false));}
export function gameNav(ui,id,ico,label){const active=ui.page===id||(ui.page==='map'&&id==='home'),image=id==='home'?art('building','hut'):id==='build'?art('building','hive'):id==='research'?art('resource','science'):id==='village'?sceneArt('bears','wave'):art('resource','star');return `<button data-nav="${id}" data-focus-key="nav-${id}" class="${active?'active':''}" ${active?'aria-current="page"':''}><span class="nav-token">${image}</span><span>${({home:'家园',build:'建造',research:'研究',village:'小熊',more:'更多'})[id]}</span></button>`;}
export function shell(vm,ui){const ns=visibleNavs(vm);return `<div class="app-shell"><div class="main-shell"><header class="topbar"><a href="#home" class="mobile-brand" aria-label="返回家园">${art('resource','bear')}<span>蜜林</span></a><div id="pause-indicator"></div><div class="topbar-right"><button class="calendar-pill" data-command="calendar">${icon(vm.calendar?.season===3?'snow':'sun')}<span>第 ${fmt(vm.calendar?.year||0)} 年 · ${esc(vm.calendar?.seasonName||'春')}</span></button><button class="icon-button" data-command="settings" aria-label="设置与存档">${icon('settings')}</button></div></header><div id="resource-bar">${resourceBar(vm,ui)}</div><main id="main-content" tabindex="-1">${page(vm,ui)}</main><footer class="game-footer"><span id="save-label">进度保存在此设备</span><button data-command="help">游戏说明</button></footer></div><nav class="bottom-nav" aria-label="主导航">${ns.map(([id,ico,label])=>gameNav(ui,id,ico,label)).join('')}</nav></div>`;}
export function hudResources(vm,ui={}){
 let preferred=[];
 if(ui.page==='research')preferred=['science',...(ui.researchTab==='workshop'?['minerals','wood']:['culture','wood'])];
 else if(ui.page==='build'){const all=vm.buildings.filter(c=>knownBuilding(vm,c)),filter=all.length>10?ui.buildFilter:'all',storage=new Set(['barn','warehouse','harbor']),community=new Set(['hut','logHouse','mansion','library','academy','amphitheatre','temple','observatory']),choices=all.filter(c=>!filter||filter==='all'||filter==='storage'&&storage.has(c.id)||filter==='community'&&community.has(c.id)||filter==='food'&&!storage.has(c.id)&&!community.has(c.id)),selected=choices.find(c=>c.id===ui.buildChoice)||choices[0];preferred=(selected?.costs||[]).map(c=>c.id);}
 else if(ui.page==='home')preferred=districts.find(d=>d.id===resolveHomeDistrict(vm,ui.district))?.materials||[];
 else if(ui.region||ui.system)preferred=({crafts:['wood','minerals','honey'],trades:['manpower','gold','furs'],faith:['faith','culture'],space:['science','starchart','oil'],challenges:['timeCrystal','temporalFlux']})[ui.region||ui.system]||[];
 const required=new Set(ui.page==='build'?preferred:ui.page==='research'?['science']:[]);
 return [...new Set([...preferred,'honey','wood',vm.resources.some(r=>r.id==='science'&&r.visible)?'science':'minerals'])].map(id=>resource(vm,id)).filter(r=>r.visible||required.has(r.id)).slice(0,3);
}
export const displayRate=(vm,r,ui={})=>vm.settings?.paused?'已暂停':ui.readOnly?'只读':rate(r.rate);
export function resourceBar(vm,ui={}){const list=hudResources(vm,ui);return `<div class="resource-ribbon">${list.map(r=>`<button class="resource-tile ${r.value>=r.max&&r.max?'at-cap':''}" data-resource="${esc(r.id)}" aria-label="${esc(r.name)} ${fmt(r.value,1)}，${displayRate(vm,r,ui)}">${art('resource',r.id)}<span class="resource-copy"><strong data-value="${r.id}">${fmt(r.value,1)}</strong><small class="${r.rate<0&&!vm.settings?.paused?'negative':''}" data-rate="${r.id}">${displayRate(vm,r,ui)}</small></span></button>`).join('')}<button class="all-resources icon-button" data-command="resources" aria-label="打开库存">${icon('box')}</button></div>`;}
export function decisionCosts(c){return `<div class="decision-costs">${(c.costs||[]).map(x=>`<div class="decision-cost ${x.owned+1e-9<x.value?'short':''}" aria-label="${esc(x.name)}，需要 ${fmt(x.value,2)}，已有 ${fmt(x.owned,2)}">${art('resource',x.id)}<span><b>${fmt(x.value,2)} ${esc(x.name)}</b><small>${x.owned+1e-9<x.value?'还差 '+fmt(Math.max(0,x.value-x.owned),2):'现有 '+fmt(x.owned,1)}</small></span></div>`).join('')||'<span>无需资源</span>'}</div>`;}


function heading(kicker,title,desc,extra=''){return `<div class="page-heading"><h1>${title}</h1>${extra}</div>`;}
function sectionTitle(title,extra=''){return `<div class="section-title"><h2>${title}</h2>${extra}</div>`;}
export function costs(card,{compact=false}={}){return `<div class="costs ${compact?'compact-costs':''}">${(card.costs||[]).map(c=>`<span class="cost ${c.owned+1e-9<c.value?'short':''}" aria-label="${esc(c.name)}，需要 ${fmt(c.value,2)}，已有 ${fmt(c.owned,2)}" title="${esc(c.name)}：已有 ${fmt(c.owned,2)} / 需要 ${fmt(c.value,2)}">${art('resource',c.id)}<span>${compact?'':esc(c.name)+' '}${fmt(c.value,2)}</span></span>`).join('')||'<span class="free-cost">无需资源</span>'}</div>`;}
function actionType(section){return ({buildings:'build',science:'research',workshop:'upgrade',crafts:'craft',faith:'faith',space:'space',trades:'trade'})[section]||section;}
export const researchIllustration=researchSubject;
export function cardArt(c,section){
 if(section==='queueOptions'){section=({build:'buildings',research:'science',upgrade:'workshop',space:'space',time:'time',faith:'faith',policy:'policies',embassy:'trades'})[c.targetType]||section;c={...c,id:c.targetId||c.id,type:c.targetType||c.type};}
 if(section==='buildingStages'){c={...c,stage:c.targetStage??c.stage};section='buildings';}
 if(section==='buildings'){const key=buildingLook(c).key||BUILDING_CELLS[c.id]||c.id;if(semanticBuildings[key])return art('building',key);if(paintedBuildings[key])return paintedBuilding(key);return art('building',key);}
 const d=illustrationFor(c,section);return art(d.kind,d.id);
}

// High-loss actions explain their scope before committing; ordinary actions stay direct.
function actionConfirmation(c){
 const existing=c.confirmationText||c.confirm||'';
 return c.type==='stage'?`${existing} ${c.description||''} 建筑效果与容量会随之变化；建议先导出存档备份。`.trim():existing;
}
function maximumConfirmation(c,section='crafts'){
 const type=c.type||actionType(section),prefix=actionConfirmation(c);
 const bill=c.costs||[],unitCost=bill.map(x=>`${fmt(x.value,2)} ${x.name}`).join('、')||'无需资源';
 if(['craft','refine'].includes(type)){
  const count=bill.reduce((n,x)=>x.value>0?Math.min(n,Math.max(0,Math.floor((x.owned+1e-9)/x.value))):n,1000000);
  const total=bill.map(x=>`${fmt(x.value*count,2)} ${x.name}`).join('、')||'无需资源';
  return `${prefix} 按当前原料最多制作 ${fmt(count)} 次${c.name}，预计消耗 ${total}。实际数量按确认时库存计算。这可能耗尽所需原料；超过成品容量的产出可能损失。继续制作？`.trim();
 }
 return `${prefix} 使用当前物资进行最多数量的${c.name}？当前单次所需：${unitCost}。批量价格可能递增，数量和总消耗按确认时库存与价格计算，可能耗尽所需物资。`.trim();
}
export function actionCard(c,section,{dense=false,vm=null}={}){if(!discovered(c))return '';const type=c.type||actionType(section),completed=c.completed;return `<article class="action-card game-item ${['science','workshop','policies'].includes(section)?'discovery-card':''} ${completed?'completed-card':''}"><button class="card-preview" data-detail="${section}:${esc(c.id)}" data-card-type="${esc(type)}" aria-label="${esc(c.name)}详情"><span class="card-illustration">${cardArt(c,section)}</span><span class="card-title"><h3>${esc(c.name)}</h3>${c.owned?`<span class="owned-badge">${completed?icon('check'):fmt(c.owned)}</span>`:''}</span></button>${completed?`<div class="complete-label">${icon('check')} 已掌握</div>`:`${costs(c,{compact:true})}${vm&&shortages(vm,c).some(x=>x.blocked)?'<span class="capacity-note">先扩充容量</span>':''}<button class="buy-button ${c.available?'':'unavailable'}" data-act="${esc(type)}" data-id="${esc(c.id)}" data-confirm="${esc(actionConfirmation(c))}" ${!c.available?'aria-disabled="true"':''} data-reason="${esc(c.reason)}" aria-label="${esc(c.name)}，${c.available?'可操作':esc(c.reason)}">${icon('plus')}<span>${section==='buildings'?'建造':section==='science'?'研究':section==='workshop'?'升级':section==='crafts'?'制作':section==='trades'?'交易':section==='policies'?'选择':section==='queueOptions'?'排队':section==='gifts'?'打开礼盒':'进行'}</span></button>`}</article>`;}
export function sceneGroups(vm){return geographicRegions(vm).map(r=>({id:r.id,label:r.name,cards:r.facilities}));}
export function buildingLocator(group){
 if(!group.cards.length)return '';
 return `<details class="building-locator" data-fold="locator-${esc(group.id)}"><summary aria-label="查找${esc(group.label)}的建筑">${icon('map')}<span>找建筑</span></summary><div class="building-locator-menu" role="group" aria-label="${esc(group.label)}的建筑">${group.cards.map(b=>`<button data-locate-building="${esc(b.id)}" data-locate-section="${esc(b.section)}" data-focus-key="locate-${esc(b.section)}-${esc(b.id)}" aria-label="定位${esc(b.name)}"><span>${esc(b.name)}</span><small>×${fmt(b.owned)}</small></button>`).join('')}</div></details>`;
}
export function world(vm,ui){
 if(ui.reuseWorld)return '<div data-world-placeholder></div>';
 const groups=sceneGroups(vm),group=groups.find(g=>g.id===resolveHomeDistrict(vm,ui.district))||groups[0],built=group.cards,mapHeight=Math.max(440,...built.map(b=>continuousLot(b.sceneSlot).y+140));
 const workers=villageWorkers(vm,{...ui,district:group.id},built);
 return `<section class="world-board era-${civilizationEra(vm).id} ${groups.length===1?'single-district':''}" data-world-key="${esc(sceneKey(vm,ui))}" data-home-district="${group.id}" aria-label="小熊家园，建筑随建设出现"><div class="world-toolbar"><button class="scene-map-return" data-nav="map" aria-label="打开世界地图">${icon('map')}</button><div class="scene-tabs" aria-label="家园区域">${groups.map(g=>`<button class="${g.id===group.id?'selected':''}" data-home-region="${g.id}" aria-pressed="${g.id===group.id}">${g.label}</button>`).join('')}</div>${buildingLocator(group)}</div><div class="world-scene ${built.length?'inhabited-scene':'empty-scene'} season-${vm.calendar?.season||0} ${vm.settings?.paused||ui.readOnly?'scene-paused':''}"><div class="continuous-map" style="--map-height:${mapHeight}px"><div class="scene-atmosphere" aria-hidden="true"></div><div class="settlement-stage">${built.map(b=>{const slot=b.sceneSlot,spot=continuousLot(slot),look=buildingLook(b);return `<button class="placed-building ${b.toggleable&&!b.enabled?'building-idle':''} ${look.expanded?'expanded-site':''}" data-look="${look.key||b.id}" data-growth-tier="${look.tier}" style="--col:${slot%2+1};--row:${Math.floor(slot/2)+1};--x:${spot.x}%;--y:${spot.y}px;--z:${spot.y};--depth:${slot<2?.88:1};--path-turn:${slot%2?-40:40}deg" data-detail="${b.section}:${b.id}" data-scene-building="${b.id}" aria-label="${esc(b.name)} ${fmt(b.owned)} 座${b.toggleable&&!b.enabled?'，已暂停':''}"><span class="building-ground" aria-hidden="true"><i class="door-path"></i><i class="garden-tuft"></i></span>${buildingSurroundings(b)}<span class="building-cluster"><span class="building-copy">${cardArt(b,b.section)}</span>${workplaceDetail(b,vm,ui)}${['library','academy'].includes(b.id)&&vm.science?.some(c=>c.completed)?`<span class="knowledge-token">${art('resource','science')}</span>`:''}</span>${b.owned>1?`<span class="building-count">×${fmt(b.owned)}</span>`:''}<span class="building-label">${esc(b.name)}${b.toggleable&&!b.enabled?' · 暂停':''}</span></button>`;}).join('')}</div><div class="resident-lane" aria-label="伙伴工作状态">${workers.map((w,i)=>`<button class="scene-worker ${w.working?'is-working':'is-resting'} worker-${w.id}" style="--worker-delay:${-i*1.1}s;--worker-x:${w.x}%;--worker-y:${w.y}px;--worker-z:${w.z}" data-workplace="${w.buildingId}" data-nav="village" data-job-focus="${w.id==='idle'?'woodcutter':w.id}" data-focus-key="worker-${w.id}" data-bear-id="${esc(w.bearId)}" aria-label="${esc(w.bearName||w.name)}，${esc(w.name)} ${fmt(w.count)} 只${w.working?'，工作中':vm.settings?.paused?'，已暂停':w.atCapacity?'，库存已满':'，待命'}，点按聊聊"><span class="worker-body"><span class="worker-frame frame-a">${sceneArt('workers',w.poses[0])}</span><span class="worker-frame frame-b">${sceneArt('workers',w.poses[1])}</span></span>${bearLifeMarkup(w)}<span class="worker-count">${art('resource',w.resource)}<span>×${fmt(w.count)}</span></span></button>`).join('')}${vm.bears?.value?`<button class="resident-status" data-nav="village" data-focus-key="population">${fmt(vm.bears.value)} 只伙伴${vm.bears.free?`<small>${fmt(vm.bears.free)} 只空闲</small>`:''}</button>`:''}</div></div></div></section>`;
}
function guideMarkup(vm){const g=guidance(vm),need=g.card?shortages(vm,g.card):[],ratio=g.arrival??g.progress??(g.card?.costs?.length?Math.min(1,...g.card.costs.map(c=>c.value?c.owned/c.value:1)):null);const attr=g.detail?`data-detail="${g.detail}"`:g.nav?`data-nav="${g.nav}" ${g.job?`data-job-focus="${g.job}"`:''}`:`data-command="${g.command||'resources'}"`;return `<button class="next-step ${g.title.includes('口粮')||g.title.includes('不够')?'food-guide':''}" ${attr}><span class="guide-picture">${g.kind==='building'&&g.card?cardArt(g.card,'buildings'):art(g.kind,g.id)}</span><span class="guide-copy"><b>${esc(g.title)}</b><small>${esc(g.reason)}</small></span>${g.card?.costs?.length===1?`<span class="guide-cost">${art('resource',g.card.costs[0].id)}<b>${fmt(Math.min(g.card.costs[0].owned,g.card.costs[0].value),1)}<small> / ${fmt(g.card.costs[0].value,1)}</small></b></span>`:''}${ratio!==null?`<span class="guide-progress" role="progressbar" aria-label="${g.arrival!==undefined?'伙伴到达进度':'物资准备进度'}" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${Math.round(Math.max(0,ratio)*100)}"><i style="width:${Math.max(0,ratio)*100}%"></i></span>`:''}</button>`;}
function home(vm,ui){const region=resolveHomeDistrict(vm,ui.district);if(region!=='village'){const cfg=districts.find(d=>d.id===region),state=regionalState(vm,region,ui),labels={crafts:'林间工坊',trades:'森林商旅',faith:'星灯祈愿',space:'远航计划',challenges:'时光研究'};return `<div class="home-controls region-home-controls" ${ui.page!=='home'?'inert aria-hidden="true"':''}><div class="region-home-actions">${state.quick.slice(0,1).map(c=>regionQuick(c,vm)).join('')}${cfg.system&&systemOpen(vm,cfg.system)?`<button class="district-system-button" data-system="${cfg.system}" aria-label="进入${labels[cfg.system]}">${icon('more')}${labels[cfg.system]}</button>`:`<button class="district-system-button" data-nav="${region==='learning'?'research':'build'}">${icon(region==='learning'?'research':'build')}${region==='learning'?'研究':'建造与管理'}</button>`}</div></div>`;}const refine=vm.actions?.find(a=>a.type==='refine'),observe=vm.actions?.find(a=>a.type==='observe'&&a.unlocked&&a.available),honey=resource(vm,'honey'),gain=Math.min(1,Math.max(0,honey.max-honey.value));return `<div class="home-controls" ${ui.page!=='home'?'inert aria-hidden="true"':''}>${observe?`<button class="sky-event" data-act="observe" data-id="${observe.id}">${icon('faith')} 观察星空</button>`:''}${guideMarkup(vm)}<div class="gather-zone"><button class="gather-button" data-act="gather" data-id="honey" data-focus-key="main-gather" ${gain<=0?'aria-disabled="true" data-reason="蜂蜜已满仓，可以建造或扩充储存。"':''} aria-label="采集蜂蜜，最多一份">${art('resource','honey')}<span><strong>采集蜂蜜</strong><small>${gain>0?'+'+fmt(gain,2):'已满仓'}</small></span></button>${refine&&discovered(refine)?`<button class="refine-button" data-act="refine" data-id="${refine.id}" ${!refine.available?'aria-disabled="true"':''} data-reason="${esc(refine.reason)}">${art('resource','wood')}<span><strong>采木</strong><small>${(refine.costs||[]).map(c=>fmt(c.value)+' '+esc(c.name)).join(' + ')}</small></span></button>`:''}</div></div>`;}

function build(vm,ui){
 const filters=[['all','全部'],['food','生产'],['storage','储存'],['community','生活']],storage=new Set(['barn','warehouse','harbor']),community=new Set(['hut','logHouse','mansion','library','academy','amphitheatre','temple','observatory']);
 const all=vm.buildings.filter(c=>knownBuilding(vm,c)),filter=all.length>10?ui.buildFilter:'all',cards=all.filter(b=>filter==='all'||filter==='storage'&&storage.has(b.id)||filter==='community'&&community.has(b.id)||filter==='food'&&!storage.has(b.id)&&!community.has(b.id)),selected=cards.find(c=>c.id===ui.buildChoice)||cards[0],stages=cardsFor(vm,'buildingStages').filter(discovered);
 return `<div class="construction-workbench"><div class="game-ribbon"><h1>建造</h1></div>${selected?`<section class="build-station" aria-label="${esc(selected.name)}建造"><button class="build-showcase" data-detail="buildings:${esc(selected.id)}" aria-label="${esc(selected.name)}详情">${cardArt(selected,'buildings')}</button><div class="blueprint-caption"><h2>${esc(selected.name)}</h2><span class="construction-owned">已建 ${fmt(selected.owned||0)} 座</span><p>${esc(Array.isArray(selected.effects)?selected.effects.join(' · '):selected.effects||'扩展家园')}</p>${buildingLook(selected).next?`<small class="growth-stage-note">${buildingLook(selected).expanded?'已扩建外观 · ':''}再建 ${fmt(buildingLook(selected).next-(selected.owned||0))} 座，${buildingLook(selected).expanded?'添置庭院设施':'外观扩建'}</small>`:buildingLook(selected).expanded?'<small class="growth-stage-note">已扩建外观</small>':''}</div><div class="build-purchase">${decisionCosts(selected)}<button class="buy-button" data-act="build" data-id="${esc(selected.id)}" data-confirm="${esc(selected.confirmationText||selected.confirm||'')}" ${!selected.available?'aria-disabled="true"':''} data-reason="${esc(selected.reason)}" aria-label="建造一座${esc(selected.name)}">${icon('plus')}建造</button></div>${shortages(vm,selected).some(x=>x.blocked)?'<p class="capacity-note">先扩充容量</p>':''}</section>`:empty('暂时没有新建筑','继续探索，新的选项会在这里出现。')}<div class="construction-tray">${all.length>10?`<div class="filter-row" role="group" aria-label="建筑筛选">${filters.map(([id,label])=>`<button class="filter-pill ${filter===id?'selected':''}" data-filter="${id}" aria-pressed="${filter===id}">${label}</button>`).join('')}</div>`:''}<div class="building-picker" role="group" aria-label="选择建筑">${cards.map(c=>`<button class="building-option ${c.id===selected?.id?'selected':''}" data-build-choice="${esc(c.id)}" data-id="${esc(c.id)}" data-focus-key="choose-${esc(c.id)}" aria-pressed="${c.id===selected?.id}" aria-label="选择${esc(c.name)}"><span class="blueprint-art">${cardArt(c,'buildings')}</span><b>${esc(c.name)}</b>${c.owned?`<small>×${fmt(c.owned)}</small>`:''}</button>`).join('')}</div></div></div><details class="fold-section construction-management" data-fold="build-management"><summary><span class="management-back">‹</span><span class="management-title">建造队列</span><span class="management-count">${vm.queue?.used?'· '+fmt(vm.queue.used):''}</span><span class="management-hint">返回建造</span></summary>${queuePanel(vm,ui)}${stages.length?`<details class="fold-section" data-fold="stages"><summary>改建方案</summary><p class="quiet-note">改建会拆售原方案，切换后需重新建造。</p><div class="card-grid">${stages.map(c=>actionCard(c,'buildingStages')).join('')}</div></details>`:''}${industryPanel(vm)}</details>`;
}

function research(vm,ui){const sections=[['science','研究'],['workshop','技艺'],['policies','约定']].filter(([id])=>cardsFor(vm,id).some(discovered)),section=sections.some(([id])=>id===ui.researchTab)?ui.researchTab:sections[0]?.[0]||'science',cards=cardsFor(vm,section).filter(discovered),newCards=cards.filter(c=>!c.completed),learned=cards.filter(c=>c.completed);return `${heading('','研究','')}${sections.length>1?`<div class="segmented">${sections.map(([id,label])=>`<button data-research-tab="${id}" aria-pressed="${section===id}" class="${section===id?'selected':''}">${label}</button>`).join('')}</div>`:''}<div class="research-notebook"><div class="notebook-intro"><span>蜜林研究手册</span><small>点插画查看发现</small></div><div class="card-grid research-path">${newCards.map(c=>actionCard(c,section,{vm})).join('')}</div></div>${!newCards.length?empty('暂时没有新的研究','建造书屋、推进现有研究后，再来看看。'):''}${learned.length?`<details class="fold-section" data-fold="completed-${section}"><summary>已掌握 · ${learned.length}</summary><div class="card-grid">${learned.map(c=>actionCard(c,section,{vm})).join('')}</div></details>`:''}`;}

const jobBuildings={ambassador:'tradepost',farmer:'hive',woodcutter:'lumberMill',miner:'mine',scholar:'library',engineer:'workshop',hunter:'hut',priest:'temple',geologist:'quarry'};
function village(vm,ui){const b=vm.bears||{};const jobs=(vm.jobs||[]).filter(discovered);return `${heading('','小熊','')}<section class="village-overview">${art('resource','bear','village-bear')}<div><h2>${fmt(b.value)} <small>只小熊</small></h2><p>${fmt(b.max)} 个住处 · ${fmt(b.free)} 只待分配</p></div><div class="village-happiness"><span>☺</span><strong>${fmt(b.happiness??100)}%</strong><small>幸福度</small></div></section>${sectionTitle('分配伙伴',`<span class="subtle-tag">${fmt(b.free)} 只空闲</span>`)}<div class="jobs-grid">${jobs.map(j=>`<article class="job-card ${!j.unlocked?'locked-card':''}" data-job="${j.id}"><div class="job-top"><div class="job-diorama" aria-hidden="true">${art('building',jobBuildings[j.id]||'hut','job-workplace')}${sceneArt('workers',workerPortrait(j.id),'job-bear')}</div><div><h3>${esc(j.name)}</h3><p>${esc(j.description)}</p></div></div><div class="job-bottom"><small>${!j.unlocked?esc(j.reason):esc((j.effects||'').replace(/\d+\.\d{6,}/g,n=>fmt(Number(n),3)))}</small><div class="stepper"><button class="icon-button" data-act="unassign" data-id="${esc(j.id)}" ${!(j.assigned>0)?'disabled':''} aria-label="减少一只${esc(j.name)}">${icon('minus')}</button><strong>${fmt(j.assigned||0)}</strong><button class="icon-button" data-act="assign" data-id="${esc(j.id)}" ${!j.available?'aria-disabled="true"':''} data-reason="${esc(j.reason||'暂时没有空闲的小熊')}" aria-label="增加一只${esc(j.name)}">${icon('plus')}</button></div></div></article>`).join('')}</div>${jobs.length?`<details class="fold-section roster-batch" data-fold="job-batch"><summary>批量分配伙伴</summary>${jobs.map(j=>`<div class="bulk-job"><b>${esc(j.name)}</b><button data-act="unassign" data-id="${esc(j.id)}" data-amount="max" ${!j.assigned?'disabled':''}>全部撤回</button><button data-act="assign" data-id="${esc(j.id)}" data-amount="max" ${!j.available?'aria-disabled="true"':''} data-reason="${esc(j.reason)}">安排空闲</button></div>`).join('')}</details>`:''}${(vm.actions||[]).some(c=>c.type==='festival'&&discovered(c))?`<section class="advanced-section">${sectionTitle('熊村节庆')}<p class="quiet-note">当前节庆剩余 ${fmt(vm.progression?.festivalDays||0)} 天</p><div class="card-grid">${vm.actions.filter(c=>c.type==='festival'&&discovered(c)).map(c=>actionCard(c,'actions')).join('')}</div></section>`:''}${cardsFor(vm,'gifts').some(c=>c.visible!==false)?`<section class="advanced-section">${sectionTitle('林间来礼')}<div class="card-grid">${cardsFor(vm,'gifts').filter(c=>c.visible!==false).map(c=>actionCard(c,'gifts')).join('')}</div></section>`:''}${leadershipPanel(vm)}${engineeringPanel(vm,{folded:true})}${!b.value?`<div class="empty-state small-empty">${icon('home')}<h3>第一位伙伴，还在路上</h3><p>建好小屋后，给森林一点时间。</p><button class="secondary-button" data-nav="build">去建一间小屋 ${icon('arrow')}</button></div>`:''}`;}
const systems=[['crafts','craft','手作工坊','把资源，做成更有用的东西。'],['trades','trade','森林商路','与远方的朋友交换物资。'],['faith','faith','星光与信仰','把每一天的希望，慢慢积攒。'],['space','space','林海之外','仰望星空，也去往星空。'],['prestige','reset','新的轮回','带着经验，再种下一片森林。'],['challenges','time','时光与挑战','给下一段旅程一些新变化。'],['achievements','faith','森林纪念册','记录成长的成就、星标与徽章。']];
export function systemOpen(vm,id){if(id==='prestige')return (vm.bears?.value||0)>0||vm.resources.some(r=>['paragon','karma','burnedParagon'].includes(r.id)&&r.value>0)||cardsFor(vm,'metaphysics').some(c=>c.owned||c.completed);if(id==='achievements')return true;if(id==='challenges')return cardsFor(vm,'challenges').some(c=>(c.id!=='ironWill'||c.unlocked||c.owned||c.completed||vm.progression?.activeChallenges?.includes(c.id))&&discovered(c))||cardsFor(vm,'time').some(discovered)||(vm.progression?.actions||[]).some(a=>['accelerate','shatter','repairCryochamber','toggleFurnace','toggleTemporalPress','useFurnaceHeat','challengeStart','reclaimReserves'].includes(a.type)&&discovered(a));if(id==='trades')return cardsFor(vm,'trades').some(discovered)||(vm.actions||[]).some(a=>['hunt','explore'].includes(a.type)&&a.unlocked);if(id==='faith')return cardsFor(vm,'faith').some(discovered)||(vm.actions||[]).some(a=>a.type==='praise'&&a.unlocked);return cardsFor(vm,id).some(discovered);}
export const explorationRegions=[
 {id:'crafts',name:'工坊林地',building:'workshop',scene:'woodland',place:'林间工坊',hint:'点工坊制作物资'},
 {id:'trades',name:'河湾商路',building:'harbor',scene:'river',place:'河畔集市',hint:'点集市拜访森林伙伴'},
 {id:'faith',name:'星灯山谷',building:'temple',scene:'twilight',place:'星灯祠堂',hint:'点祠堂查看祈愿'},
 {id:'space',name:'群星海岸',building:'spaceport',scene:'twilight',place:'观星台',hint:'点观星台准备远行'},
 {id:'challenges',name:'时光遗迹',building:'chronosphere',scene:'twilight',place:'时光石门',hint:'点石门查看时光与挑战'}
];
export function explorationKey(vm){return JSON.stringify([civilizationEra(vm).id,geographicRegions(vm).map(r=>[r.id,r.facilities.map(b=>[b.id,b.owned,b.stage])]),['crafts','trades','faith','space','challenges','prestige'].filter(id=>systemOpen(vm,id))]);}
function worldMap(vm,ui){
 if(ui.reuseMap)return '<div data-map-placeholder></div>';
 const regions=geographicRegions(vm),era=civilizationEra(vm),height=Math.max(460,regions.length*220+100);

 return `<div class="world-map-view era-${era.id}" data-world-map-key="${esc(explorationKey(vm))}"><header class="world-map-header"><h1>世界地图</h1><span>${era.name}</span></header><div class="world-map-scroll" tabindex="0" aria-label="世界地图，上下滑动浏览地区"><div class="exploration-map world-map-canvas" style="height:${height}px">${regions.map((r,i)=>`<button class="world-region geographic-region terrain-${r.scene}" style="--region-x:${i%2?65:35}%;--region-y:${115+i*220}px" data-home-region="${r.id}" aria-label="进入${r.name}"><span class="area-preview" aria-hidden="true"><i class="area-river"></i><i class="area-road"></i>${r.facilities.slice(0,3).map((b,n)=>`<span class="area-building area-building-${n}">${cardArt(b,b.section)}</span>`).join('')}<i class="area-trees"></i></span><strong>${r.name}</strong></button>`).join('')}</div></div></div>`;
}
export function explorationMenu(vm){
 const entries=[
  ['crafts','手作工坊','building','workshop'],['trades','森林商旅','building','harbor'],
  ['faith','星灯祈愿','building','temple'],['space','远航计划','building','spaceport'],
  ['challenges','时光研究','building','chronosphere'],['prestige','传承','resource','karma'],
 ].filter(([id])=>systemOpen(vm,id));
 const tile=([id,label,kind,artId],command=false)=>`<button class="more-hub-entry" data-${command?'command':'system'}="${id}"><span class="more-hub-art" aria-hidden="true">${kind==='icon'?icon(artId):art(kind,artId)}</span><span>${label}</span></button>`;
 const utilities=[['achievements','纪念册','resource','star'],['journal','手记','resource','science'],['help','说明','icon','help'],['settings','设置','icon','settings']];
 return `<nav class="more-hub" aria-label="更多功能">${entries.length?`<section class="more-hub-section" aria-label="已开启的功能"><div class="more-hub-grid">${entries.map(entry=>tile(entry)).join('')}</div></section>`:''}<section class="more-hub-section more-hub-utilities" aria-label="记录与设置"><div class="more-hub-grid">${utilities.map(entry=>tile(entry,entry[0]!=='achievements')).join('')}</div></section></nav>`;
}
export function regionKey(vm,ui){return regionalStateKey(vm,ui.region,ui);}
function regionQuick(c,vm){return `<button class="regional-quick-action" data-region-quick="true" data-act="${esc(c.type)}" data-id="${esc(c.id)}" data-confirm="${esc(actionConfirmation(c))}" ${!c.available?'aria-disabled="true"':''} data-reason="${esc(c.reason||'物资不足')}" aria-label="${esc(c.type==='refine'?'采木一次':c.type==='hunt'?'巡林一次':'制作一次'+c.name)}"><span class="quick-output">${art('resource',c.output||'manpower')}<b>${esc(c.type==='refine'?'采木':c.type==='hunt'?'巡林':c.name)}</b></span><span class="quick-cost">${(c.costs||[]).map(x=>`${fmt(x.value,2)} ${esc(x.name)}`).join(' · ')||'无需物资'}</span></button>`;}
export function recipePanel(vm,ui){
 const cards=cardsFor(vm,'crafts').filter(discovered),selected=cards.find(c=>c.id===ui.recipeChoice)||cards[0];
 if(!selected)return empty('暂时没有配方','继续研究，学习新的制作方法。');
 const tenAvailable=selected.available&&(selected.costs||[]).every(c=>c.owned+1e-9>=c.value*10),tenCost=(selected.costs||[]).map(c=>`${fmt(c.value*10,2)} ${c.name}`).join('、');
 const batch=`<div class="recipe-batch" role="group" aria-label="批量制作${esc(selected.name)}"><button class="secondary-button" data-act="${esc(selected.type||'craft')}" data-id="${esc(selected.id)}" data-amount="10" data-confirm="${esc(selected.confirmationText||selected.confirm||'')}" ${!tenAvailable?'aria-disabled="true"':''} data-reason="${esc(selected.reason||'制作十次的原料不足')}" aria-label="制作${esc(selected.name)}十次，消耗${esc(tenCost)}">制作 ×10</button><button class="secondary-button" data-act="${esc(selected.type||'craft')}" data-id="${esc(selected.id)}" data-amount="max" ${!selected.available?'aria-disabled="true"':''} data-reason="${esc(selected.reason||'物资不足')}" data-confirm="${esc(maximumConfirmation(selected))}" aria-label="用当前原料制作最多数量的${esc(selected.name)}">制作最多</button></div>`;
 return `<div class="recipe-workbench"><div class="recipe-picker" role="group" aria-label="选择制作配方">${cards.map(c=>`<button data-recipe-choice="${esc(c.id)}" class="recipe-option ${c.id===selected.id?'selected':''}" aria-pressed="${c.id===selected.id}" aria-label="选择配方${esc(c.name)}">${art('resource',c.output||c.id)}<b>${esc(c.type==='refine'?'采木':c.name)}</b></button>`).join('')}</div><p class="recipe-unit-cost">每次所需原料</p><div class="recipe-purchase">${decisionCosts(selected)}<button class="buy-button" data-region-quick="true" data-act="${esc(selected.type||'craft')}" data-id="${esc(selected.id)}" data-confirm="${esc(selected.confirmationText||selected.confirm||'')}" ${!selected.available?'aria-disabled="true"':''} data-reason="${esc(selected.reason||'物资不足')}" aria-label="制作${esc(selected.name)}">${selected.type==='refine'?'采木':'制作'} ×1</button></div>${batch}<button class="text-button recipe-details" data-detail="crafts:${esc(selected.id)}" aria-label="${esc(selected.name)}配方详情与批量制作">配方详情与批量制作 ${icon('arrow')}</button>${engineeringPanel(vm,{recipeId:selected.id,folded:true})}</div>`;
}
function more(vm,ui){if(ui.system)return system(vm,ui);return `${heading('','更多','')}${explorationMenu(vm)}`;}

function system(vm,ui,embedded=false){
 if(!systemOpen(vm,ui.system))return empty('这片天地还没开启','继续建设家园，再来看看。');
 if(ui.system==='achievements')return `<button class="back-button" data-system="">${icon('arrow')} 返回更多</button>${heading('','纪念册','')}${achievementsPanel(vm)}`;
 const [id,ico,name,desc]=systems.find(s=>s[0]===ui.system)||systems[0],late=vm.progression||{},cards=cardsFor(vm,id).filter(discovered);
 const categories={trades:['feedElders','buyBlackcoin','sellBlackcoin','crashBlackcoin','embassy'],faith:['adore','transcend','sacrifice','payPactDebt'],prestige:['burnParagon'],challenges:['accelerate','shatter','repairCryochamber','toggleFurnace','toggleTemporalPress','useFurnaceHeat','challengeStart','reclaimReserves']};
 const customs=(late.actions||[]).filter(a=>discovered(a)&&(categories[id]||[]).includes(a.type)),actions=(vm.actions||[]).filter(discovered).filter(a=>id==='trades'?['hunt','explore','embassy'].includes(a.type):id==='faith'?a.type==='praise':id==='crafts'?a.type==='festival':false);
 const extra=(id==='prestige'?cardsFor(vm,'metaphysics'):id==='challenges'?cardsFor(vm,'time'):[]).filter(discovered);
 return `${embedded?'':`<button class="back-button" data-system="">${icon('arrow')} 返回更多</button>${heading('A WIDER WORLD',name,desc)}`}${id==='prestige'?prestige(vm):''}${id==='trades'&&!embedded?diplomacyPanel(vm):''}${id==='crafts'&&!embedded?`<button class="catalog-toggle" data-region-catalog="${ui.regionCatalog?'false':'true'}">${ui.regionCatalog?'快捷制作':'图鉴'}</button>`:''}${id==='challenges'?challengePanel(vm):''}${id==='faith'?`<div class="system-metrics"><div><span>累计颂愿</span><b>${fmt(late.praised,2)}</b></div><div><span>灵悟</span><b>${fmt(late.faithRatio,3)}</b></div><div><span>升华</span><b>${fmt(late.transcendence)}</b></div></div>${late.pacts?`<p class="quiet-note">约定 ${fmt(late.pacts.active)} 项 · 空余位置 ${fmt(late.pacts.slots)} · 债务 ${fmt(late.pacts.debt,2)} · 效果系数 ${fmt(late.pacts.penalty,3)}</p>`:''}`:''}${id==='challenges'?`<div class="system-metrics"><div><span>时热</span><b>${fmt(late.heat,2)}</b></div><div><span>熔炉热量</span><b>${fmt(late.furnaceHeat,2)}</b></div><div><span>时流加速</span><b>${late.accelerating?'已开启 ×'+fmt(vm.rateMultiplier??1,2):'未开启'}</b></div></div>`:''}<div class="card-grid progression-actions">${actions.map(c=>actionCard(c,'actions')).join('')}${customs.map(c=>actionCard(c,'progressionActions')).join('')}</div>${extra.length?`${sectionTitle(id==='prestige'?'长久的领悟':'时光工坊')}<div class="card-grid progression-actions">${extra.map(c=>actionCard(c,id==='prestige'?'metaphysics':'time')).join('')}</div>`:''}${cards.length&&id!=='challenges'?(id==='crafts'&&!ui.regionCatalog?recipePanel(vm,ui):`<div class="card-grid">${cards.map(c=>actionCard(c,id)).join('')}</div>`):''}${id==='crafts'&&ui.regionCatalog?engineeringPanel(vm,{folded:true}):''}${!cards.length&&!customs.length&&!extra.length&&id!=='prestige'?empty('这段旅程尚未开启','需要先在知识与建造中推进相应的研究。此版本仅展示已经实现的系统。'):''}`;
}
function prestige(vm){const preview=vm.resetPreview||{};return `<section class="prestige-panel">${icon('reset')}<h2>新的森林，熟悉的你。</h2><p>重启会清空本轮资源、建筑与研究。符合条件的传承资源会保留下来。</p><div class="prestige-preview">${Object.entries(preview).filter(([k,v])=>typeof v==='number').map(([k,v])=>`<div><span>${esc(({karma:'将获得的业力',paragon:'将获得的传承',kittens:'本轮居民',bears:'本轮居民',karmaGain:'业力进度',preservedBears:'保留居民',retention:'资源保留比例'})[k]||k)}</span><b>${k==='retention'?fmt(v*100,1)+'%':fmt(v,2)}</b></div>`).join('')}</div>${Object.keys(preview.preserved||{}).length?`<div class="retained-preview"><h3>预计保留的资源</h3>${Object.entries(preview.preserved).map(([id,v])=>`<span>${esc(vm.resources.find(r=>r.id===id)?.name||id)} <b>${fmt(v,2)}</b></span>`).join('')}</div>`:''}<button class="danger-outline" data-command="reset">查看重启确认 ${icon('arrow')}</button><p class="quiet-note">只有确认后，才会开始新的旅程。</p></section>`;}
export function page(vm,ui){if(ui.page==='more'&&ui.region){const [p,id]=regionDestination(vm,ui.region,ui.regionSite).split('/');ui={...ui,page:p,district:resolveHomeDistrict(vm,ui.region),region:'',regionSite:'',system:p==='more'?id:''};}return `<div class="playfield ${ui.page==='home'?'home-view':'panel-view'}" >${world(vm,ui)}${home(vm,ui)}${ui.page==='home'?'':`<section class="game-sheet sheet-${ui.page} ${ui.page==='map'?'explore-overview map-overview':ui.page==='more'?(!ui.system?'more-overview':'explore-utility'):''}" aria-label="${({build:'建造',research:'研究',village:'小熊',map:'世界地图',more:'更多'})[ui.page]||'菜单'}">${ui.region?'':`<button class="sheet-close icon-button" data-nav="home" aria-label="收起，返回家园">${icon('close')}</button>`}<div class="game-sheet-body">${(ui.page==='build'?build:ui.page==='research'?research:ui.page==='village'?village:ui.page==='map'?worldMap:more)(vm,ui)}</div></section>`}</div>`;}

function empty(title,description){return `<div class="empty-state">${icon('lock')}<h3>${title}</h3><p>${description}</p></div>`;}
export function resourcesDialog(vm,focusId){return `<div class="inventory-list">${vm.resources.filter(r=>r.visible||r.id===focusId).map(r=>`<div class="inventory-item ${r.id===focusId?'highlighted':''}">${art('resource',r.id)}<div class="inventory-body"><div class="inventory-line"><b>${esc(r.name)}</b><strong>${fmt(r.value,2)} <small>/ ${fmt(r.max,1)}</small></strong></div><div class="inventory-meter"><i style="width:${pct(r.value,r.max)}%"></i></div><div class="inventory-line"><small>${esc(r.description||'')}</small><span class="rate ${r.rate<0&&!vm.settings?.paused?'negative':''}">${displayRate(vm,r)}</span></div>${r.breakdown?.length?`<details class="production-breakdown" data-breakdown="${esc(r.id)}" ${r.id===focusId?'open':''}><summary>${vm.settings?.paused?'恢复后的收支明细':'收支明细'}</summary>${r.breakdown.map(item=>`<div><span>${esc(item.label)}</span><b class="${item.rate<0?'negative':''}">${rate(item.rate)}</b></div>`).join('')}</details>`:''}</div></div>`).join('')}</div><div class="notice">${icon('help')}<p>每秒速率已计入当前季节、生产建筑、已分配工作与消耗。达到容量后，多余产出不会继续储存。</p></div>`;}
function saleControls(c,section){
 const type=section==='buildings'?'sell':['sellFaith','sellSpace'].includes(c.sellType)?c.sellType:null;
 if(!type||!(c.owned>0))return '';
 const allLabel=type==='sellFaith'?'出售至一级':'出售全部';
 const unit=type==='sellFaith'?'级':'座',label=type==='sellFaith'?'祈愿升级':type==='sellSpace'?'星球设施':'建筑';
 const explanation=c.sellDescription||c.sellConfirmationText||(type==='sell'?'拆售通常返还当前造价的 50% 可退物资；石油、煤油与钍不返还。住处和库存容量也会降低。':'出售会降低对应等级或设施数量，退款按当前规则结算并受库存容量限制。');
 const warning=[c.sellConfirmationText||explanation,'出售会降低对应效果，容量与产量可能随之降低；退款受库存容量限制，无法直接恢复。'].join(' ');
 return `<div class="detail-management"><h3>管理这项${label}</h3><p class="quiet-note">${esc(explanation)}</p><button class="danger-outline" data-act="${type}" data-id="${esc(c.id)}" ${c.sellable===false?'aria-disabled="true"':''} data-reason="${esc(c.sellReason||'')}" data-confirm="${esc(`出售一${unit}${c.name}？${warning}`)}">出售一${unit}</button><button class="danger-outline" data-act="${type}" data-id="${esc(c.id)}" ${c.sellable===false?'aria-disabled="true"':''} data-reason="${esc(c.sellReason||'')}" data-amount="max" data-confirm="${esc(`${type==='sellFaith'?`出售${c.name}的 ${fmt(Math.max(0,c.owned-1))} 级，并保留一级？`:`出售全部 ${fmt(c.owned)} ${unit}${c.name}？`}${c.sellAllConfirmationText?c.sellAllConfirmationText+' ':''}${warning}`)}">${allLabel}</button></div>`;
}
export function detailDialog(c,section,vm={}){const blocked=vm.resources?shortages(vm,c).filter(x=>x.blocked):[];return `<div class="detail-hero">${cardArt(c,section)}<div><span class="eyebrow">${section==='buildings'?'森林建筑':'成长与发现'}</span><h2>${esc(c.name)}</h2>${c.owned?`<span class="subtle-tag">已有 ${fmt(c.owned)}</span>`:''}</div></div><p class="detail-description">${esc(c.description)}</p>${c.effects?`<div class="effect-box">${icon('leaf')}<span>${esc(Array.isArray(c.effects)?c.effects.join('；'):c.effects)}</span></div>`:''}${blocked.length?`<div class="notice capacity-notice">${icon('box')}<p>${blocked.map(x=>`${esc(x.name)}容量 ${fmt(x.capacity)}，需要 ${fmt(x.value)}。`).join('')}先增加储存容量。</p></div>`:''}<h3 class="detail-subtitle">所需资源</h3><div class="detail-costs">${(c.costs||[]).map(x=>`<div>${art('resource',x.id)}<span>${esc(x.name)}</span><b class="${x.owned<x.value?'negative':''}">${fmt(x.owned,2)}<small> / ${fmt(x.value,2)}</small></b>${x.owned>=x.value?icon('check'):icon('time')}</div>`).join('')||'<p class="quiet-note">无需额外资源</p>'}</div>${!c.available&&!c.completed?`<div class="notice">${icon(c.unlocked?'time':'lock')}<p>${esc(c.reason||'资源尚未准备齐全')}</p></div>`:''}${c.completed?'<div class="complete-label">已完成</div>':`<button class="primary-button full-width" data-act="${c.type||actionType(section)}" data-id="${esc(c.id)}" data-confirm="${esc(actionConfirmation(c))}" ${!c.available?'aria-disabled="true"':''} data-reason="${esc(c.reason)}">${icon('plus')} ${section==='buildings'?'建造一座':section==='science'?'研究':'进行'}${esc(c.name)}</button>`}${!c.completed&&!c.oneTime&&['build','craft','refine','trade','embassy','faith','space','time'].includes(c.type||actionType(section))?`<button class="secondary-button full-width batch-button" data-act="${esc(c.type||actionType(section))}" data-id="${esc(c.id)}" data-amount="max" data-confirm="${esc(maximumConfirmation(c,section))}" ${!c.available?'aria-disabled="true"':''} data-reason="${esc(c.reason)}">使用当前物资进行最多数量</button>`:''}${saleControls(c,section)}${c.owned&&c.toggleable?`<button class="secondary-button full-width" data-act="toggle" data-id="${c.id}">${c.enabled?'暂停':'恢复'}生产</button>`:''}`;}
export function settingsDialog(vm,settings){return `<div class="settings-group"><h3>游戏节奏</h3><button class="setting-row" role="switch" aria-checked="${!!vm.settings?.paused}" data-command="pause">${icon(vm.settings?.paused?'play':'pause')}<span><b>${vm.settings?.paused?'继续生长':'暂停游戏'}</b><small>${vm.settings?.paused?'当前时间与生产均已暂停':'暂停后，时间和资源停止推进'}</small></span><span class="switch ${vm.settings?.paused?'checked':''}"><i></i></span></button><button class="setting-row" role="switch" aria-checked="${!!vm.settings?.offline}" data-command="offline">${icon('time')}<span><b>离线结算</b><small>${vm.settings?.offline?'开启：返回时按规则结算离线生产':'默认关闭；开启后，离开期间也可结算'}</small></span><span class="switch ${vm.settings?.offline?'checked':''}"><i></i></span></button><button class="setting-row" role="switch" aria-checked="${!!settings.reducedMotion}" data-command="motion">${icon('leaf')}<span><b>减少动态效果</b><small>让界面更安静，也更省电</small></span><span class="switch ${settings.reducedMotion?'checked':''}"><i></i></span></button></div><div class="settings-group"><h3>把森林好好保存</h3><p class="quiet-note">自动保存在当前浏览器。清理浏览器数据或更换设备前，请导出备份。</p><button class="list-button" data-command="save">${icon('save')}<span>立即保存</span>${icon('arrow')}</button><button class="list-button" data-command="export">${icon('download')}<span>导出存档文件</span>${icon('arrow')}</button><button class="list-button" data-command="import">${icon('upload')}<span>导入存档文件</span>${icon('arrow')}</button><input id="save-file" type="file" accept=".json,application/json" hidden></div><div class="settings-group"><h3>关于这片森林</h3><button class="list-button" data-command="help">${icon('help')}<span>玩法、规则与制作说明</span>${icon('arrow')}</button><span class="version-label">Beargame 蜜林 · v6.5.2 · 本地存档 · 无账号 / 无广告</span></div>`;}
export function helpDialog(vm){return `<div class="help-content"><div class="help-brand">${art('resource','bear')}<h2>Beargame · 蜜林小熊文明</h2><p>从一滴蜂蜜，生长出自己的森林。</p></div><h3>开始你的第一天</h3><ol><li>点击「采集蜂蜜」积累资源。</li><li>建造蜂箱，获得随时间增长的蜂蜜产量。</li><li>带上蜂蜜作口粮，前往林地采木，再建小屋和图书馆。</li><li>给入住的小熊安排工作，积累知识，打开新的发展道路。</li></ol><h3>留意季节与库存</h3><p>季节会影响蜂蜜产量，小熊也会持续消耗食物。库存满后，多余资源不再储存。点顶部资源即可查看每秒净收支与容量。</p><h3>离开以后</h3><p>你的森林只保存在当前设备的浏览器中。离线结算默认关闭；在设置中开启后，再次打开会按规则结算。暂停状态不会推进。建议定期导出存档。</p><h3>当前版本</h3><p>可用功能会随家园发展逐步开放。具体操作与解锁条件以游戏内显示为准。</p>${coverageHtml(vm.coverage)}<h3>操作保护</h3><p>日常采集、建造和制作直接进行。制作最多、批量购买、拆售和改建会先说明消耗或后果，再请你确认。没有通用撤销；重启、挑战重开与重要转化前，请先导出存档备份。</p><h3>操作与无障碍</h3><p>支持触屏和键盘；Tab 移动焦点，Enter 或空格执行操作，Esc 关闭弹窗。减少动态效果可在设置中开启。</p></div>`;}
